mapper.select:
select tps.*,tmp.min_account_full_name
from tb_procurement_scheme tps
left join tb_min_project tmp on tps.project_code = tmp.min_account_code

    tps.state != 2

        and tps.project_code = #{queryVO.projectCode,jdbcType=VARCHAR}


        and tps.procurement_scheme_code like concat('%',#{queryVO.procurementSchemeCode,jdbcType=VARCHAR},'%')


        and  tps.procurement_scheme_name like concat('%',#{queryVO.procurementSchemeName,jdbcType=VARCHAR},'%')


        and  tps.procurement_plan_type = #{queryVO.procurementPlanType,jdbcType=INTEGER}


        and tps.create_id = #{queryVO.procurementOfficer,jdbcType=BIGINT}


        and tps.procurement_officer = #{queryVO.procurementOfficer,jdbcType=BIGINT}


        and tps.state = #{queryVO.state,jdbcType=INTEGER}


order by tps.create_time desc

select tps.*, tn.notice_status, tn.id noticeId
from tb_procurement_scheme tps
left join tb_tender_notice tn on tn.scheme_id = tps.id and tn.del_flag = 0

    tps.del_flag = 0

        and  tps.procurement_scheme_code like concat('%',#{queryVO.procurementSchemeCode,jdbcType=VARCHAR},'%')


        and tn.id = #{queryVO.noticeId,jdbcType=BIGINT}


        and  tps.procurement_scheme_name like concat('%',#{queryVO.procurementSchemeName,jdbcType=VARCHAR},'%')


        and  tps.procurement_plan_type = #{queryVO.procurementPlanType,jdbcType=INTEGER}


        and  tps.procurement_type = #{queryVO.procurementType,jdbcType=INTEGER}


        and (
        tps.create_id = #{queryVO.procurementOfficer,jdbcType=BIGINT}

            or tps.finance_confirm_id = #{queryVO.financeConfirmId, jdbcType = VARCHAR}

        )


        and (
        tps.procurement_officer = #{queryVO.procurementOfficer,jdbcType=BIGINT}

            or tps.finance_confirm_id = #{queryVO.financeConfirmId, jdbcType = VARCHAR}

        )


        and tps.procurement_officer_name like concat('%',#{queryVO.procurementOfficerName,jdbcType=VARCHAR},'%')


        and  tps.state = #{queryVO.state,jdbcType=INTEGER}


        and  tn.notice_status = #{queryVO.noticeStatus,jdbcType=INTEGER}


        and tps.project_code = #{queryVO.projectCode,jdbcType=VARCHAR}






        and (tps.project_code in

            #{projectCode}

        )


order by tps.create_time desc
